//! The passive tree: layout data, a Character's allocated passives, and
//! Calibration onto the in-game tree.
//!
//! `data/tree.json` is generated by `scripts/gen-tree.mjs` from GGG's skill
//! tree export (layout) and RePoE (Client Log id -> node id).

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

use serde::{Deserialize, Serialize};

use crate::{
    log::{LogEvent, LogRecord},
    pob::{Build, TreeStage},
};

const TREE_JSON: &str = include_str!("../data/tree.json");

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NodeKind {
    Normal,
    Notable,
    Keystone,
    Mastery,
    Jewel,
    ClassStart,
    AscendancyStart,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TreeNode {
    pub id: u32,
    pub name: String,
    pub kind: NodeKind,
    /// The cluster the node sits in; a mastery is reached through its group.
    #[serde(default)]
    pub group: u32,
    pub x: f64,
    pub y: f64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub ascendancy: Option<String>,
    /// Part of a bloodline (an alternate ascendancy).
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub bloodline: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub class_start: Option<u8>,
    /// A mastery's effects, in the order the game lists them.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub mastery_effects: Vec<u32>,
    pub out: Vec<u32>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TreeClass {
    pub name: String,
    pub start_node: Option<u32>,
    pub ascendancies: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
struct TreeFile {
    classes: Vec<TreeClass>,
    nodes: Vec<TreeNode>,
    log_ids: HashMap<String, u32>,
}

#[derive(Debug, Clone)]
pub struct PassiveTree {
    pub classes: Vec<TreeClass>,
    pub nodes: Vec<TreeNode>,
    index: HashMap<u32, usize>,
    log_ids: HashMap<String, u32>,
    /// Undirected connections between main-tree nodes.
    adjacent: HashMap<u32, Vec<u32>>,
    /// Tree node id -> Client Log passive id.
    log_id_of: HashMap<u32, String>,
}

impl PassiveTree {
    /// The bundled tree.
    pub fn bundled() -> Self {
        let file: TreeFile = serde_json::from_str(TREE_JSON).expect("bundled tree.json is valid");
        let index = file
            .nodes
            .iter()
            .enumerate()
            .map(|(i, n)| (n.id, i))
            .collect();
        let mut adjacent: HashMap<u32, Vec<u32>> = HashMap::new();
        for n in &file.nodes {
            for &o in &n.out {
                adjacent.entry(n.id).or_default().push(o);
                adjacent.entry(o).or_default().push(n.id);
            }
        }
        let log_id_of = file
            .log_ids
            .iter()
            .map(|(log, node)| (*node, log.clone()))
            .collect();
        Self {
            classes: file.classes,
            nodes: file.nodes,
            index,
            log_ids: file.log_ids,
            adjacent,
            log_id_of,
        }
    }

    pub fn node(&self, id: u32) -> Option<&TreeNode> {
        self.index.get(&id).map(|&i| &self.nodes[i])
    }

    /// The Client Log passive id for a tree node.
    pub fn log_id_for_node(&self, node: u32) -> Option<&str> {
        self.log_id_of.get(&node).map(String::as_str)
    }

    /// The main-tree node drawn nearest `at` (game-window pixels), if one is
    /// close enough to have been what the player clicked.
    pub fn node_at(&self, transform: &Transform, at: (f64, f64)) -> Option<u32> {
        let reach = (60.0 * transform.scale).max(10.0);
        self.nodes
            .iter()
            .filter(|n| n.ascendancy.is_none() && n.kind != NodeKind::ClassStart)
            .map(|n| {
                let (x, y) = transform.apply(n.x, n.y);
                (n.id, (x - at.0).hypot(y - at.1))
            })
            .filter(|(_, d)| *d <= reach)
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .map(|(id, _)| id)
    }

    /// An ascendancy's start node ("Necromancer").
    pub fn ascendancy_start(&self, ascendancy: &str) -> Option<u32> {
        self.nodes
            .iter()
            .find(|n| {
                n.kind == NodeKind::AscendancyStart
                    && n.ascendancy
                        .as_deref()
                        .is_some_and(|a| a.eq_ignore_ascii_case(ascendancy))
            })
            .map(|n| n.id)
    }

    /// An ascendancy's planned nodes not yet allocated, in an order that can be
    /// taken: outward from the ascendancy start, nearest first.
    pub fn ascendancy_points(
        &self,
        allocated: &HashSet<u32>,
        start: u32,
        target: &[u32],
    ) -> Vec<u32> {
        let mut remaining: HashSet<u32> = target
            .iter()
            .copied()
            .filter(|id| !allocated.contains(id) && *id != start)
            .collect();
        let mut have: HashSet<u32> = allocated.clone();
        have.insert(start);
        let mut order = Vec::new();
        while let Some(path) = self.cheapest_path(&have, &remaining, &|_| true) {
            for id in path {
                remaining.remove(&id);
                have.insert(id);
                order.push(id);
            }
        }
        let mut rest: Vec<u32> = remaining.into_iter().collect();
        rest.sort_unstable();
        order.extend(rest);
        order
    }

    /// Tree node for a passive id as printed in the Client Log.
    pub fn node_for_log_id(&self, log_id: &str) -> Option<u32> {
        self.log_ids.get(log_id).copied()
    }

    /// Next Points: the Tree Stage's nodes not yet allocated, in an order that
    /// can actually be allocated (each next to the class start or an earlier
    /// node), heading for what matters first: the cheapest route to a
    /// keystone, then into a planned mastery's group, then to a notable, then
    /// the remaining small nodes. Routes only use nodes in the plan.
    /// Masteries and ascendancy nodes aren't numbered; nodes that can't be
    /// reached through the plan come last.
    pub fn next_points(
        &self,
        allocated: &HashSet<u32>,
        start: u32,
        target: &[u32],
        masteries: &[u32],
    ) -> Vec<u32> {
        let mut remaining: HashSet<u32> = target
            .iter()
            .copied()
            .filter(|id| !allocated.contains(id))
            .filter(|id| {
                self.node(*id).is_some_and(|n| {
                    n.ascendancy.is_none()
                        && !matches!(n.kind, NodeKind::Mastery | NodeKind::ClassStart)
                })
            })
            .collect();
        let mut have: HashSet<u32> = allocated.iter().copied().collect();
        have.insert(start);
        let kind_of = |id: u32| self.node(id).map(|n| n.kind);
        let group_of = |id: u32| self.node(id).map_or(u32::MAX, |n| n.group);

        // Mastery groups still to reach (no allocated node in the group yet).
        let mut mastery_groups: Vec<u32> = masteries
            .iter()
            .filter_map(|m| self.node(*m))
            .filter(|m| m.kind == NodeKind::Mastery)
            .map(|m| m.group)
            .filter(|g| !have.iter().any(|h| group_of(*h) == *g))
            .collect();
        mastery_groups.sort_unstable();
        mastery_groups.dedup();

        let mut order = Vec::new();
        loop {
            let found = {
                let groups = &mastery_groups;
                let goals: [Box<dyn Fn(u32) -> bool>; 4] = [
                    Box::new(|id| kind_of(id) == Some(NodeKind::Keystone)),
                    Box::new(move |id| groups.contains(&group_of(id))),
                    Box::new(|id| kind_of(id) == Some(NodeKind::Notable)),
                    Box::new(|_| true),
                ];
                goals
                    .iter()
                    .find_map(|goal| self.cheapest_path(&have, &remaining, goal))
            };
            let Some(path) = found else {
                break;
            };
            for id in path {
                remaining.remove(&id);
                have.insert(id);
                mastery_groups.retain(|g| *g != group_of(id));
                order.push(id);
            }
        }
        let mut rest: Vec<u32> = remaining.into_iter().collect();
        rest.sort_unstable();
        order.extend(rest);
        order
    }

    /// Shortest route from any node in `have`, stepping only onto nodes in
    /// `through`, to the nearest one satisfying `goal`. Ties go to the lower
    /// node id, so the result is stable. Excludes the starting node.
    fn cheapest_path(
        &self,
        have: &HashSet<u32>,
        through: &HashSet<u32>,
        goal: &dyn Fn(u32) -> bool,
    ) -> Option<Vec<u32>> {
        let mut from: Vec<u32> = have.iter().copied().collect();
        from.sort_unstable();
        let mut prev: HashMap<u32, u32> = HashMap::new();
        let mut seen: HashSet<u32> = have.clone();
        let mut frontier = from;
        while !frontier.is_empty() {
            let mut next_frontier = Vec::new();
            for &id in &frontier {
                let mut neighbours: Vec<u32> = self.adjacent.get(&id).cloned().unwrap_or_default();
                neighbours.sort_unstable();
                for n in neighbours {
                    if through.contains(&n) && seen.insert(n) {
                        prev.insert(n, id);
                        next_frontier.push(n);
                    }
                }
            }
            next_frontier.sort_unstable();
            if let Some(&hit) = next_frontier.iter().find(|&&id| goal(id)) {
                let mut path = vec![hit];
                let mut cur = hit;
                while let Some(&p) = prev.get(&cur) {
                    if have.contains(&p) {
                        break;
                    }
                    path.push(p);
                    cur = p;
                }
                path.reverse();
                return Some(path);
            }
            frontier = next_frontier;
        }
        None
    }

    /// Option numbers for a Tree Stage's mastery picks (by tree node id).
    pub fn planned_mastery_picks(&self, effects: &[(u32, u32)]) -> Vec<MasteryPick> {
        effects
            .iter()
            .filter_map(|&(node, effect)| {
                let n = self.node(node)?;
                let index = n.mastery_effects.iter().position(|e| *e == effect)?;
                Some(MasteryPick {
                    node,
                    option: index as u8 + 1,
                })
            })
            .collect()
    }

    /// Which option (1-based, as listed in game) each picked mastery effect is.
    pub fn mastery_picks(&self, masteries: &BTreeMap<String, u32>) -> Vec<MasteryPick> {
        masteries
            .iter()
            .filter_map(|(mastery, effect)| {
                let node = self.node(self.node_for_log_id(mastery)?)?;
                let index = node.mastery_effects.iter().position(|e| e == effect)?;
                Some(MasteryPick {
                    node: node.id,
                    option: index as u8 + 1,
                })
            })
            .collect()
    }

    /// The base class for a class or ascendancy name ("Necromancer" -> Witch).
    pub fn base_class(&self, class: &str) -> Option<&TreeClass> {
        self.classes.iter().find(|c| {
            c.name.eq_ignore_ascii_case(class)
                || c.ascendancies.iter().any(|a| a.eq_ignore_ascii_case(class))
        })
    }

    /// Main-tree nodes (excluding the ascendancy panel) for a set of log ids.
    pub fn allocated_nodes<'a>(&self, log_ids: impl IntoIterator<Item = &'a String>) -> Vec<u32> {
        log_ids
            .into_iter()
            .filter_map(|id| self.node_for_log_id(id))
            .filter(|id| self.node(*id).is_some_and(|n| n.ascendancy.is_none()))
            .collect()
    }

    /// The second Calibration point: the Scion start in the middle of the tree
    /// (the Witch start at the top for a Scion). Big, obvious, and far from
    /// every other class start, so the scale comes out accurate.
    pub fn calibration_partner(&self, start: u32) -> Option<&TreeNode> {
        const SCION: u8 = 0;
        const WITCH: u8 = 3;
        let class_start = |i: u8| self.nodes.iter().find(|n| n.class_start == Some(i));
        let scion = class_start(SCION)?;
        if scion.id == start {
            class_start(WITCH)
        } else {
            Some(scion)
        }
    }
}

/// Maps tree coordinates onto game-window pixels: `screen = tree * scale + offset`.
/// The in-game tree is never rotated, so scale and offset are enough.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Transform {
    pub scale: f64,
    pub offset_x: f64,
    pub offset_y: f64,
}

impl Transform {
    /// From two tree points and where the player clicked them on screen.
    /// `None` if the points coincide (no scale can be derived).
    pub fn from_two_points(
        tree_a: (f64, f64),
        screen_a: (f64, f64),
        tree_b: (f64, f64),
        screen_b: (f64, f64),
    ) -> Option<Self> {
        let tree_dist = (tree_b.0 - tree_a.0).hypot(tree_b.1 - tree_a.1);
        let screen_dist = (screen_b.0 - screen_a.0).hypot(screen_b.1 - screen_a.1);
        if tree_dist < 1.0 || screen_dist < 1.0 {
            return None;
        }
        let scale = screen_dist / tree_dist;
        Some(Self {
            scale,
            offset_x: screen_a.0 - tree_a.0 * scale,
            offset_y: screen_a.1 - tree_a.1 * scale,
        })
    }

    pub fn apply(&self, x: f64, y: f64) -> (f64, f64) {
        (
            x * self.scale + self.offset_x,
            y * self.scale + self.offset_y,
        )
    }

    /// Nudge by whole screen pixels.
    pub fn nudged(self, dx: f64, dy: f64) -> Self {
        Self {
            offset_x: self.offset_x + dx,
            offset_y: self.offset_y + dy,
            ..self
        }
    }

    /// Scale by `factor` around a fixed screen point.
    pub fn zoomed(self, factor: f64, around: (f64, f64)) -> Self {
        Self {
            scale: self.scale * factor,
            offset_x: around.0 - (around.0 - self.offset_x) * factor,
            offset_y: around.1 - (around.1 - self.offset_y) * factor,
        }
    }
}

/// Fully zoomed out, the in-game tree draws at `game height / 10_000` screen
/// pixels per tree unit (measured at 1440p: 0.0000998 per pixel of height).
pub const ZOOMED_OUT_SCALE_PER_PX: f64 = 1.0e-4;

/// Which point the player is being asked to click. Calibration is done with
/// the in-game tree zoomed fully out.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(tag = "step", rename_all = "camelCase")]
pub enum Calibrating {
    /// One click on the class start, reusing the learned zoomed-out scale.
    Quick,
    ClassStart,
    Partner {
        class_start_at: (f64, f64),
    },
}

/// The tree Overlay's own state (persisted between sessions).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase")]
pub struct TreeOverlay {
    pub visible: bool,
    pub calibrating: Option<Calibrating>,
    pub transform: Option<Transform>,
    /// "Fix points": clicks add or remove nodes, for when the log is wrong
    /// (allocations cancelled in game aren't logged).
    pub editing: bool,
    /// Fully zoomed out, the in-game tree's scale is proportional to the game
    /// window's height. Measured by a two-click Calibration; overrides
    /// [`ZOOMED_OUT_SCALE_PER_PX`].
    pub zoomed_out_scale_per_px: Option<f64>,
    /// Showing the ascendancy panel instead of the main tree.
    pub ascendancy: bool,
    /// Per ascendancy: a correction to where its panel sits, measured by a
    /// middle-click on the ascendancy start (tree units added to the data's
    /// position). Only needed if [`ascendancy_placement`] is off for a class.
    pub ascendancy_fixes: BTreeMap<String, (f64, f64)>,
}

/// How far the ascendancy start sits from the class start, towards the tree's
/// centre. Measured from fully zoomed-out screenshots: Necromancer ~945,
/// Juggernaut ~964.
pub const ASCENDANCY_DISTANCE: f64 = 955.0;
/// How far a bloodline's start sits from the class start, away from the
/// tree's centre (opposite the class's own ascendancy; Marauder ~918).
pub const BLOODLINE_DISTANCE: f64 = 920.0;

/// Where the game draws an ascendancy start node, in tree units: in the small
/// circle by the class art, a fixed distance from the class start, towards
/// the centre of the tree (or away from it, for a bloodline), at the main
/// tree's scale.
pub fn ascendancy_placement(class_start: (f64, f64), bloodline: bool) -> (f64, f64) {
    let (x, y) = class_start;
    let len = x.hypot(y);
    // The Scion sits in the middle: a guess (below), correctable in game.
    let (ux, uy) = if len < 1.0 {
        (0.0, 1.0)
    } else {
        (-x / len, -y / len)
    };
    let d = if bloodline {
        -BLOODLINE_DISTANCE
    } else {
        ASCENDANCY_DISTANCE
    };
    (x + ux * d, y + uy * d)
}

impl TreeOverlay {
    pub fn toggle_visible(&mut self) {
        self.visible = !self.visible;
        if !self.visible {
            self.calibrating = None;
            self.editing = false;
        }
    }

    pub fn toggle_editing(&mut self) {
        self.editing = !self.editing && self.transform.is_some();
        if self.editing {
            self.visible = true;
            self.calibrating = None;
        }
    }

    /// Cycle Calibration: one click -> full two-click -> cancelled.
    pub fn toggle_calibration(&mut self) {
        self.calibrating = match self.calibrating {
            None => Some(Calibrating::Quick),
            Some(Calibrating::Quick) => Some(Calibrating::ClassStart),
            Some(_) => None,
        };
        if self.calibrating.is_some() {
            self.visible = true;
        }
    }

    pub fn toggle_ascendancy(&mut self) {
        self.ascendancy = !self.ascendancy;
        self.editing = false;
        self.calibrating = None;
    }

    /// The alignment of one ascendancy panel: the main tree's, shifted so the
    /// ascendancy start lands where [`ascendancy_placement`] puts it, plus any
    /// correction measured in game.
    pub fn ascendancy_transform(
        &self,
        tree: &PassiveTree,
        ascendancy: &str,
        ascendancy_start: u32,
        class_start: u32,
    ) -> Option<Transform> {
        let t = self.transform?;
        let (asc, class) = (tree.node(ascendancy_start)?, tree.node(class_start)?);
        let (px, py) = ascendancy_placement((class.x, class.y), asc.bloodline);
        let (fx, fy) = self
            .ascendancy_fixes
            .get(ascendancy)
            .copied()
            .unwrap_or_default();
        let (dx, dy) = (px - asc.x + fx, py - asc.y + fy);
        Some(Transform {
            scale: t.scale,
            offset_x: t.offset_x + dx * t.scale,
            offset_y: t.offset_y + dy * t.scale,
        })
    }

    /// In ascendancy mode, the player clicked an ascendancy start (in a circle
    /// by the class art): correct where that panel is drawn, relative to the
    /// main tree's alignment.
    pub fn fix_ascendancy(
        &mut self,
        tree: &PassiveTree,
        ascendancy: &str,
        ascendancy_start: u32,
        class_start: u32,
        at: (f64, f64),
    ) {
        let Some(t) = self.transform else {
            return;
        };
        let (Some(asc), Some(class)) = (tree.node(ascendancy_start), tree.node(class_start)) else {
            return;
        };
        let clicked = ((at.0 - t.offset_x) / t.scale, (at.1 - t.offset_y) / t.scale);
        let placed = ascendancy_placement((class.x, class.y), asc.bloodline);
        self.ascendancy_fixes.insert(
            ascendancy.to_owned(),
            (clicked.0 - placed.0, clicked.1 - placed.1),
        );
    }

    /// The player marked their class start at `at` (game-window pixels) with
    /// the tree fully zoomed out: the scale follows from the window height, the
    /// position from the click. Used by middle-click and one-click Calibration.
    pub fn align_on_class_start(
        &mut self,
        tree: &PassiveTree,
        class_start: u32,
        at: (f64, f64),
        game_height: f64,
    ) {
        self.calibrating = None;
        let Some(start) = tree.node(class_start) else {
            return;
        };
        let per_px = self
            .zoomed_out_scale_per_px
            .unwrap_or(ZOOMED_OUT_SCALE_PER_PX);
        let scale = per_px * game_height;
        self.transform = Some(Transform {
            scale,
            offset_x: at.0 - start.x * scale,
            offset_y: at.1 - start.y * scale,
        });
    }

    /// The player clicked `at` (game-window pixels) during Calibration, in a
    /// game window `game_height` pixels tall.
    pub fn click(
        &mut self,
        tree: &PassiveTree,
        class_start: u32,
        at: (f64, f64),
        game_height: f64,
    ) {
        match self.calibrating {
            Some(Calibrating::Quick) => {
                self.align_on_class_start(tree, class_start, at, game_height)
            }
            Some(Calibrating::ClassStart) => {
                self.calibrating = Some(Calibrating::Partner { class_start_at: at });
            }
            Some(Calibrating::Partner { class_start_at }) => {
                let (Some(start), Some(partner)) = (
                    tree.node(class_start),
                    tree.calibration_partner(class_start),
                ) else {
                    self.calibrating = None;
                    return;
                };
                if let Some(t) = Transform::from_two_points(
                    (start.x, start.y),
                    class_start_at,
                    (partner.x, partner.y),
                    at,
                ) {
                    self.transform = Some(t);
                    self.calibrating = None;
                    if game_height > 0.0 {
                        self.zoomed_out_scale_per_px = Some(t.scale / game_height);
                    }
                }
                // Same spot clicked twice: keep asking for the partner.
            }
            None => {}
        }
    }
}

/// A picked mastery effect, shown as its position in the game's list.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct MasteryPick {
    pub node: u32,
    /// 1-based.
    pub option: u8,
}

/// Everything the tree Overlay draws.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TreeView {
    pub visible: bool,
    pub editing: bool,
    pub calibrating: Option<Calibrating>,
    pub transform: Option<Transform>,
    pub character: Option<String>,
    pub class_start: Option<TreeNode>,
    /// The second Calibration point.
    pub partner: Option<TreeNode>,
    /// Allocated main-tree nodes.
    pub allocated: Vec<u32>,
    pub masteries: Vec<MasteryPick>,
    /// The Build's Tree Stage being worked towards, if a Build is imported.
    pub stage: Option<String>,
    /// Index of that stage, all stage titles, and whether it was picked by hand.
    pub stage_index: Option<usize>,
    pub stages: Vec<String>,
    pub stage_by_hand: bool,
    /// Next Points towards that stage, in allocation order.
    pub planned: Vec<u32>,
    /// The stage's mastery picks not yet made as planned.
    pub planned_masteries: Vec<MasteryPick>,
    /// Showing the ascendancy panels instead of the main tree.
    pub ascendancy: bool,
    /// The Character's ascendancy (from its class, or the Build's plan).
    pub ascendancy_name: Option<String>,
    /// The ascendancy and, if one is taken or planned, a bloodline.
    pub ascendancies: Vec<AscendancyPanel>,
}

/// One ascendancy circle on the tree.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AscendancyPanel {
    pub name: String,
    pub bloodline: bool,
    pub start: TreeNode,
    pub transform: Option<Transform>,
    /// Allocated and planned (in taking order) nodes.
    pub allocated: Vec<u32>,
    pub planned: Vec<u32>,
}

/// The Tree Stage to work towards at `level`, unless the player picked one
/// (`chosen`). Stages with a target level ("LvLing Tree lvl 36"): the one with
/// the lowest target at or above `level`, else the highest. Without targets:
/// the first stage not yet complete.
pub fn pick_stage<'a>(
    stages: &'a [TreeStage],
    level: u32,
    allocated: &HashSet<u32>,
    chosen: Option<usize>,
) -> Option<(usize, &'a TreeStage)> {
    if let Some(i) = chosen
        && let Some(stage) = stages.get(i)
    {
        return Some((i, stage));
    }
    let targeted: Vec<(usize, &TreeStage, u32)> = stages
        .iter()
        .enumerate()
        .filter_map(|(i, s)| s.target.map(|t| (i, s, t)))
        .collect();
    if !targeted.is_empty() {
        let next = targeted
            .iter()
            .filter(|(_, _, t)| *t >= level)
            .min_by_key(|(i, _, t)| (*t, *i));
        let best = next.or_else(|| {
            targeted
                .iter()
                .max_by_key(|(i, _, t)| (*t, usize::MAX - *i))
        });
        return best.map(|(i, s, _)| (*i, *s));
    }
    stages
        .iter()
        .enumerate()
        .find(|(_, s)| s.nodes.iter().any(|n| !allocated.contains(n)))
        .or_else(|| stages.iter().enumerate().next_back())
}

impl TreeView {
    /// For the Active Character's Profile (`None` before one is known).
    pub fn build(
        tree: &PassiveTree,
        overlay: &TreeOverlay,
        profile: Option<&crate::profile::Profile>,
    ) -> Self {
        let empty_passives = BTreeSet::new();
        let empty_masteries = BTreeMap::new();
        let character = profile.map(|p| p.name.as_str());
        let class = profile.and_then(|p| p.class.as_deref());
        let passives = profile.map_or(&empty_passives, |p| &p.passives);
        let masteries = profile.map_or(&empty_masteries, |p| &p.masteries);
        let build: Option<(&Build, u32)> =
            profile.and_then(|p| p.build.as_ref().map(|b| (b, p.level)));
        let chosen_stage = profile.and_then(|p| p.tree_stage);
        let start = class
            .and_then(|c| tree.base_class(c))
            .and_then(|c| c.start_node)
            .and_then(|id| tree.node(id));
        let allocated = tree.allocated_nodes(passives);
        let have: HashSet<u32> = allocated.iter().copied().collect();
        let picks = tree.mastery_picks(masteries);
        let title_of = |i: usize, st: &TreeStage| {
            st.title
                .clone()
                .unwrap_or_else(|| format!("Tree {}", i + 1))
        };
        let stages: Vec<String> = build
            .map(|(b, _)| {
                b.tree_stages
                    .iter()
                    .enumerate()
                    .map(|(i, st)| title_of(i, st))
                    .collect()
            })
            .unwrap_or_default();
        let picked = match (build, start) {
            (Some((b, level)), Some(_)) => pick_stage(&b.tree_stages, level, &have, chosen_stage),
            _ => None,
        };
        // The ascendancy: the class itself once ascended, else the Build's plan.
        let asc_name: Option<String> = class
            .filter(|c| {
                tree.classes
                    .iter()
                    .any(|k| k.ascendancies.iter().any(|a| a.eq_ignore_ascii_case(c)))
            })
            .map(str::to_owned)
            .or_else(|| build.and_then(|(b, _)| b.ascendancy.clone()));
        let logged: Vec<u32> = passives
            .iter()
            .filter_map(|p| tree.node_for_log_id(p))
            .collect();
        // A bloodline, if any of its nodes are taken or planned.
        let planned_ids: Vec<u32> = picked.map(|(_, st)| st.nodes.clone()).unwrap_or_default();
        let bloodline_name: Option<String> = logged
            .iter()
            .chain(&planned_ids)
            .filter_map(|id| tree.node(*id))
            .find(|n| n.bloodline)
            .and_then(|n| n.ascendancy.clone());
        let ascendancies: Vec<AscendancyPanel> = [asc_name.clone(), bloodline_name]
            .into_iter()
            .flatten()
            .filter_map(|name| {
                let start_node = tree.node(tree.ascendancy_start(&name)?)?;
                let in_panel = |id: &u32| {
                    tree.node(*id).is_some_and(|n| {
                        n.ascendancy
                            .as_deref()
                            .is_some_and(|a| a.eq_ignore_ascii_case(&name))
                    })
                };
                let allocated: Vec<u32> = logged.iter().copied().filter(in_panel).collect();
                let target: Vec<u32> = planned_ids.iter().copied().filter(in_panel).collect();
                let have: HashSet<u32> = allocated.iter().copied().collect();
                Some(AscendancyPanel {
                    transform: start.and_then(|c| {
                        overlay.ascendancy_transform(tree, &name, start_node.id, c.id)
                    }),
                    planned: tree.ascendancy_points(&have, start_node.id, &target),
                    bloodline: start_node.bloodline,
                    start: start_node.clone(),
                    allocated,
                    name,
                })
            })
            .collect();
        let stage_index = picked.map(|(i, _)| i);
        let stage = picked.map(|(i, st)| title_of(i, st));
        let (planned, planned_masteries) = match (picked, start) {
            (Some((_, st)), Some(s)) => (
                tree.next_points(
                    &have,
                    s.id,
                    &st.nodes,
                    &st.mastery_effects
                        .iter()
                        .map(|(m, _)| *m)
                        .collect::<Vec<_>>(),
                ),
                tree.planned_mastery_picks(&st.mastery_effects)
                    .into_iter()
                    .filter(|p| !picks.contains(p))
                    .collect(),
            ),
            _ => (Vec::new(), Vec::new()),
        };
        Self {
            stage,
            stage_index,
            stage_by_hand: chosen_stage.is_some_and(|i| i < stages.len()),
            stages,
            planned,
            planned_masteries,
            ascendancy: overlay.ascendancy,
            ascendancies,
            ascendancy_name: asc_name,
            visible: overlay.visible,
            editing: overlay.editing,
            calibrating: overlay.calibrating,
            transform: overlay.transform,
            character: character.map(str::to_owned),
            class_start: start.cloned(),
            partner: start.and_then(|s| tree.calibration_partner(s.id)).cloned(),
            allocated,
            masteries: picks,
        }
    }
}

/// "Fix points": flip whether the node clicked at `at` is allocated.
/// Returns the node's name when something changed.
pub fn toggle_allocation(
    tree: &PassiveTree,
    transform: &Transform,
    at: (f64, f64),
    passives: &mut BTreeSet<String>,
    masteries: &mut BTreeMap<String, u32>,
) -> Option<String> {
    let node = tree.node_at(transform, at)?;
    let log_id = tree.log_id_for_node(node)?.to_owned();
    if !passives.remove(&log_id) {
        passives.insert(log_id);
    } else {
        masteries.remove(&log_id);
    }
    tree.node(node).map(|n| n.name.clone())
}

/// A Character's allocated passives and mastery picks, by Client Log id.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Allocations {
    pub passives: BTreeSet<String>,
    pub masteries: BTreeMap<String, u32>,
}

/// Rebuild a Character's allocations from a whole Client Log.
///
/// Allocation lines don't name the Character, so they are attributed to
/// whoever levelled up most recently, the same assumption the timer makes.
pub fn allocations_from_log(
    records: impl IntoIterator<Item = LogRecord>,
    character: &str,
) -> Allocations {
    let mut active: Option<String> = None;
    let mut a = Allocations::default();
    for record in records {
        let mine = active.as_deref() == Some(character);
        match record.event {
            LogEvent::LevelUp {
                character: name,
                level,
                ..
            } => {
                // A reused name starts over.
                if name == character && level == 2 {
                    a = Allocations::default();
                }
                active = Some(name);
            }
            LogEvent::PassiveAllocated { id, .. } if mine => {
                a.passives.insert(id);
            }
            LogEvent::PassiveUnallocated { id, .. } if mine => {
                a.passives.remove(&id);
                a.masteries.remove(&id);
            }
            LogEvent::MasteryEffectAllocated { effect, mastery } if mine => {
                a.passives.insert(mastery.clone());
                a.masteries.insert(mastery, effect);
            }
            _ => {}
        }
    }
    a
}

